"""Native cinematic, radar input, timed audio and exact ship-art verification."""
from pathlib import Path
import sys,json,hashlib
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'_BUILD_SOURCE'));import shoot
OUT=ROOT/'_shots/hq_live_1010';OUT.mkdir(parents=True,exist_ok=True);checks=[];errors=[]
def check(name,value,data=None):
 checks.append(dict(name=name,passed=bool(value),data=data));print(('PASS ' if value else 'FAIL ')+name,flush=True)
 if not value:print(json.dumps(data),flush=True)
port,stop=shoot.serve(str(ROOT))
try:
 with sync_playwright() as pw:
  br=pw.chromium.launch(args=['--autoplay-policy=no-user-gesture-required']);p=br.new_page(viewport=dict(width=1280,height=900));p.set_default_timeout(120000)
  p.on('pageerror',lambda e:errors.append(str(e)))
  p.on('console',lambda m:errors.append(m.text[:800]) if m.type=='error' or 'draw error' in m.text else None)
  p.on('response',lambda r:errors.append('HTTP '+str(r.status)+': '+r.url) if r.status>=400 else None)
  p.goto(f'http://127.0.0.1:{port}/index.html');p.wait_for_function('window.__bofFrames>4');p.evaluate(shoot.TRAP_RAF);p.mouse.click(650,450)
  def frames(n):
   for i in range(0,n,30):
    e=p.evaluate(shoot.STEP,min(30,n-i))
    if e:errors.append(e);break
    p.wait_for_timeout(4)
  def start(index=0,pilot='cole'):
   p.evaluate("q=>{BOFCinematicDirector.cancel();run.mode='campaign';run.pilot=q.pilot;story=null;fb2Talk=null;s6Opening=null;const beats=BOFCinematicDirector.script(5).filter(b=>/^hq10_background_/.test(b.bg||''));window.hq10Done=0;BOFCinematicDirector.play('hq-native',beats,()=>{hq10Done++;setState(GS.TITLE);});BOFCinematicDirector.current.i=q.index;}",dict(index=index,pilot=pilot))
   p.wait_for_function('()=>hq10Warm()',polling=50);frames(1)
  def shot(name):p.screenshot(path=str(OUT/(name+'.png')))
  start(0);frames(50);shot('arrival-early');q=p.evaluate("({key:BOFCinematicDirector.current.beats[0].bg,ships:HQ10.draws.ship_cole,rect:HQ10.rect})")
  check('HQ arrival draws the actual authored Cole ship',q['key']=='hq10_background_00' and q['ships']>0,q)
  frames(220);shot('arrival-landed');check('Landing advances on the live cinematic clock',p.evaluate('BOFCinematicDirector.current._hq10.t')>4)
  start(1);frames(145);shot('attack-live');q=p.evaluate("({red:HQ10.draws.fb2_stealth_red,green:HQ10.draws.fb2_stealth_green})")
  check('HQ attack uses the actual red and green stealth fighter plates',q['red']>0 and q['green']>0,q)
  start(2);frames(50);shot('map-acquisition');q=p.evaluate("(()=>{const M=BOFCinematicDirector.current._hq10;return{time:M.t,seen:M.tracks.filter(q=>q.seen).length,radar:HQ10.draws.radar};})()")
  check('Radar fills progressively before entering the held sweep',0<q['time']<2 and 0<q['seen']<20 and q['radar']>0,q)
  frames(200);shot('map-live');q=p.evaluate("(()=>{const M=BOFCinematicDirector.current._hq10;window.hq10Position=hq10TrackPosition(M.tracks[0],M.t);return{seen:M.tracks.filter(q=>q.seen).length,contacts:HQ10.events.filter(q=>q.event==='contact').length,sounds:HQ10.events.filter(q=>q.event==='sound'&&q.cue==='contact')};})()")
  check('Held radar discovers moving tracks and plays authored contact beeps',q['seen']>=18 and q['contacts']>=18 and q['sounds'] and all(s['available'] for s in q['sounds']),q)
  check('Both lower signal instruments render the authored animated waveform',p.evaluate('HQ10.draws.signal||0')>2)
  frames(25);q=p.evaluate("(()=>{const M=BOFCinematicDirector.current._hq10,p=hq10TrackPosition(M.tracks[0],M.t);return Math.hypot(p.x-hq10Position.x,p.y-hq10Position.y);})()")
  check('Map ships change geographic position between native frames',q>.005,q)
  p.keyboard.press('ArrowRight');frames(1);q=p.evaluate('({selected:BOFCinematicDirector.current._hq10.selected,beat:BOFCinematicDirector.current.i})')
  check('Directional input selects a contact without advancing dialogue',q['selected']!=0 and q['beat']==2,q)
  p.keyboard.press('j');frames(1);q=p.evaluate("(()=>{const s=BOFCinematicDirector.current;window.hq10Scanned=s._hq10.selected;return {beat:s.i,scan:s._hq10.scan};})()")
  check('A begins a real acquisition scan instead of skipping the map',q['beat']==2 and q['scan'] is not None,q)
  frames(45);shot('map-selected-scanning');frames(50);q=p.evaluate("(()=>{const M=BOFCinematicDirector.current._hq10;return{confirmed:M.tracks[hq10Scanned].confirmed,scan:M.scan,events:HQ10.events.filter(q=>q.event==='scan-complete')};})()")
  check('Scan completion marks the selected contact and ends the progress phase',q['confirmed'] and q['scan'] is None and q['events'],q)
  frames(115);shot('map-alien-discovered')
  q=p.evaluate("(()=>{const M=BOFCinematicDirector.current._hq10;return{signal:M.tracks.find(q=>q.kind==='signal').seen,t:M.t};})()")
  check('Alien interference becomes a separate discovered signal',q['signal'],q)
  point=p.evaluate("(()=>{const s=BOFCinematicDirector.current,M=s._hq10,B=HQ10.mapBounds,i=M.tracks.findIndex((q,i)=>q.seen&&i!==M.selected&&q.kind==='friendly'),q=hq10TrackPosition(M.tracks[i],M.t),r=cv.getBoundingClientRect(),W=cutsceneViewWidth();return {i,x:r.x+(B.x+q.x*B.w)/W*r.width,y:r.y+(B.y+q.y*B.h)/VH*r.height};})()")
  p.mouse.move(point['x'],point['y']);p.mouse.down();frames(1);p.mouse.up();frames(1)
  q=p.evaluate('({selected:BOFCinematicDirector.current._hq10.selected,scan:BOFCinematicDirector.current._hq10.scan,beat:BOFCinematicDirector.current.i})')
  check('Pointer hit testing uses the full cinematic viewport and scans its contact',q['selected']==point['i'] and q['scan'] is not None and q['beat']==2,q)
  before=p.evaluate("HQ10.events.filter(q=>q.event==='sound').length");p.evaluate('()=>{BOFCinematicDirector.draw();BOFCinematicDirector.draw();BOFCinematicDirector.draw();}')
  check('Drawing the map again cannot duplicate sounds',p.evaluate("HQ10.events.filter(q=>q.event==='sound').length")==before)
  p.keyboard.press('k');frames(1);q=p.evaluate('({beat:BOFCinematicDirector.current.i,controls:BOFCinematicDirector.current._hq10.controls,scan:BOFCinematicDirector.current._hq10.scan})')
  check('B returns from radar inspection to dialogue without skipping the beat',q['beat']==2 and not q['controls'] and q['scan'] is None,q)
  p.keyboard.press('j');frames(1);q=p.evaluate('({beat:BOFCinematicDirector.current.i,background:BOFCinematicDirector.current.beats[BOFCinematicDirector.current.i].bg})')
  check('A resumes the ordinary cinematic continuation after Back',q['beat']==3 and q['background']=='hq10_background_03',q)
  frames(210);shot('scramble-live');q=p.evaluate('({formation:hq10Formation(),draws:HQ10.draws})')
  check('Scramble renders five unique actual pilot ships',len(set(q['formation']))==5 and all(q['draws'].get('ship_'+k,0)>0 for k in q['formation']),q)
  start(2);frames(20);p.keyboard.press('Enter');frames(2)
  check('Start still skips the scene and calls its continuation exactly once',p.evaluate('!BOFCinematicDirector.active&&hq10Done===1&&state===GS.TITLE'))
  start(2);frames(895);check('Radar remains active for its specified reading interval',p.evaluate('BOFCinematicDirector.current?.i===2'))
  frames(30);check('Radar progresses automatically into the scramble',p.evaluate('BOFCinematicDirector.current?.i===3'))
  for pilot in ['cole','axel','freezer','yuri','maverick','falva','lizzie','decker','juggernaut']:
   start(0,pilot);frames(90);shot('pilot-'+pilot)
  q=p.evaluate('HQ10.draws');check('All nine landing variants draw their own exact authored airframes',all(q.get('ship_'+k,0)>0 for k in ['cole','axel','freezer','yuri','maverick','falva','lizzie','decker','juggernaut']),q)
  p.set_viewport_size(dict(width=480,height=900));start(2,'decker');frames(270);shot('map-narrow')
  q=p.evaluate('({W:cutsceneViewWidth(),rect:HQ10.rect,map:HQ10.mapBounds,H:VH})')
  check('Narrow viewport keeps the full radar housing above the dialogue',q['rect']['x']>=0 and q['rect']['x']+q['rect']['w']<=q['W']+.1 and q['rect']['y']+q['rect']['h']<=q['H']*.701,q)
  q=p.evaluate('()=>{const r=cv.getBoundingClientRect();return{x:r.width/cutsceneViewWidth(),y:r.height/VH};}')
  check('Narrow cinematic preserves ship, radar and portrait proportions in actual CSS pixels',abs(q['x']/q['y']-1)<.005,q)
  q=p.evaluate("(()=>{const M=BOFCinematicDirector.current._hq10,B=HQ10.mapBounds,r=cv.getBoundingClientRect(),W=cutsceneViewWidth(),i=M.tracks.findIndex(q=>q.seen&&q.kind==='friendly'),q=hq10TrackPosition(M.tracks[i],M.t);return {i,x:r.x+(B.x+q.x*B.w)/W*r.width,y:r.y+(B.y+q.y*B.h)/VH*r.height};})()")
  p.mouse.move(q['x'],q['y']);p.mouse.down();frames(1);p.mouse.up();frames(1)
  check('Narrow-view pointer still selects the intended ship',p.evaluate('BOFCinematicDirector.current._hq10.selected')==q['i'])
  check('All requested radar sounds exist in the actual audio bank',p.evaluate("['retinaCharge','retinaLockBeep','blip','select','av3_target_acquire','thruster'].every(k=>typeof Audio.SFX[k]==='function')"))
  check('No page, console or asset errors',not errors,errors);br.close()
finally:stop()
report=dict(passed=sum(q['passed'] for q in checks),failed=sum(not q['passed'] for q in checks),checks=checks,errors=errors)
(OUT/'native-report.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print(json.dumps(dict(passed=report['passed'],failed=report['failed'],errors=errors)),flush=True)
sys.exit(1 if report['failed'] else 0)
